pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // The owner of c is the deployer of setUp, i.e. this test contract.
        // Any other address is an admissible non-owner caller.
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));

        // Adversarial environment: the non-owner first funds c via the payable
        // fallback with a fuzzed amount, so the balance to withdraw is set up.
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool funded, ) = address(c).call{value: amount}("");
        assertTrue(funded); // setup sanity, still reads c's actual behavior

        // Property under test: for ANY non-owner actor, withdrawAll() must
        // revert. On the reference contract the onlyOwner guard always makes
        // it revert; on the mutant the non-owner's call succeeds and drains
        // the contract.
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
}

