pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));
        vm.assume(actor.code.length == 0); // plain EOA so the payout transfer always succeeds

        // actor deposits `amount` into c via the payable fallback
        vm.deal(actor, amount + 1);
        vm.prank(actor);
        (bool depOk, ) = address(c).call{value: amount}("");
        require(depOk, "deposit failed");
        require(address(c).balance == amount, "balance setup failed");

        // a NON-OWNER tries to drain the contract
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // Rule: for a non-owner, withdrawAll must revert AND the funds must stay in c.
        assertTrue(!ok && address(c).balance == amount);
    }
}

