pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        // Deployed from this test contract, so owner == address(this).
        c = new C();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        // WIDE admissible domain: any amount, any actor EXCEPT the actual owner
        // (owner = whoever deployed c = this test contract). Previously the
        // fuzzed actor could coincide with the owner, making the mutant's
        // behavior identical on those runs.
        vm.assume(actor != c.owner());

        // Actor sends `amount` Ether into the contract via the payable fallback.
        if (amount > 0) {
            vm.deal(actor, amount);
            vm.prank(actor);
            (bool sent, ) = address(c).call{value: amount}("");
            require(sent, "deposit failed");
        }

        uint256 balanceBefore = address(c).balance;
        require(balanceBefore == amount);

        // Drive the boundary entry: withdrawAll.
        vm.prank(actor);
        try c.withdrawAll() {
            // Reference: unreachable for a non-owner. On P this branch never executes.
            assertTrue(false, "non-owner drained contract");
        } catch {
            // Reference P: withdrawAll always reverts for non-owners (onlyOwner guard),
            // so the contract keeps every deposit. Mutant M lets the actor drain it,
            // so if we ever reach the catch, the balance MUST still be intact —
            // on M, the drain succeeds and this fails differently; more decisively,
            // on M the try-branch fires and the assertion above breaks.
            assertTrue(address(c).balance == balanceBefore, "balance changed on revert");
        }
    }
}

