pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 fundAmt, uint256 w) public {
        vm.assume(fundAmt > 0);

        // fund the contract through its payable fallback using a fuzzer-dealt funder
        address funder = makeAddr("funder");
        vm.deal(funder, fundAmt);
        vm.prank(funder);
        (bool okFund, ) = address(c).call{value: fundAmt}("");
        assertTrue(okFund);

        // admissible withdrawal: a strict partial amount of the balance
        w = bound(w, 1, fundAmt - 1);
        uint256 balBefore = address(c).balance;

        // owner (deployer, i.e. this test contract) performs a partial withdrawal
        vm.prank(address(this));
        bool ok;
        try c.withdraw(w) { ok = true; } catch { ok = false; }

        // Universal rule: after a successful partial withdrawal of w (< balance),
        // the contract retains a positive balance (exactly balBefore - w).
        // The mutant drains the full balance, leaving 0.
        assertTrue(!ok || address(c).balance == balBefore - w && address(c).balance > 0);
    }
}

