pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 numDeposits, uint256 numWithdrawals, address depositor) public {
        vm.assume(depositor != address(this) && depositor != address(0));
        bound(amount, 0, 1 ether);
        bound(numDeposits, 1, 10);
        bound(numWithdrawals, 0, 10);

        vm.deal(depositor, amount * numDeposits);
        for (uint256 i = 0; i < numDeposits; i++) {
            vm.prank(depositor);
            (bool ok, ) = address(c).call{value: amount}("");
            assertTrue(ok, "fallback deposit failed");
        }

        vm.deal(address(c), address(c).balance + numWithdrawals * 1 wei);
        for (uint256 j = 0; j < numWithdrawals; j++) {
            c.withdrawAll();
        }

        // depositsCount must reflect ONLY fallback deposits, never owner-only calls
        assertTrue(c.depositsCount() == numDeposits);
    }
}

